EquipmentLendingPolicy {
  Applicability: staff ∪ registeredStudents with currentRecords;
  StandardLendingLimit: 14 days;
  ExtendedRequests: duration>14 days → require administratorReview before approval;
  Renewal: max 1 × 7-day renewal allowed; renewal requires recordedApproval; verbalPermission invalid;
  Penalties: missed(deadline ∈ {return, response, reporting}) → $15/day penalty;
  Documentation: staff must log missedDeadlines/exceptions in centralSystem to distinguish approvedExceptions vs oversights;
  MedicalEquipment: normally excluded; lending requires writtenDeptApproval;
  Emergencies: justify immediateProtection; responsiblePerson must create record post-action;
  Supervisors: clarifyProcedures allowed; cannot waive eligibilityRules independently;
  Appeals: submit to operationsDirector within 10 businessDays specifying disputedDecision;
  Audits: annual sample approvedRequests + rejectedRequests;
  Exceptions: personalConvenience ≠ validReason;
  Conflicts: controlledHandbookVersion prevails over other versions;
  Questions: direct to operations; no informalPrecedent resolutions allowed.
}
